from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M02','R e gestione dei dati','Dall’importazione alla tabella analitica verificabile')
m.sezione_nuova('Progetto e stato della sessione')
m.pagina('Lo script dichiara la procedura',
'''Un’analisi può dipendere da oggetti creati durante prove interattive e assenti dal codice consegnato. Per rendere ricostruibile la procedura, lo script deve dichiarare gli input, eseguire le trasformazioni nell’ordine necessario e salvare i risultati. La cartella del progetto fornisce il riferimento per i percorsi relativi, mentre la separazione fra dati acquisiti e prodotti dell’analisi rende riconoscibile la provenienza. Il riavvio della sessione permette di verificare se le dipendenze operative siano effettivamente esplicitate.''',
'''Un percorso viene interpretato rispetto alla cartella di lavoro del processo. La posizione del file sorgente può essere diversa; per questo motivo il progetto viene aperto dalla sua radice prima di eseguire i laboratori. Il comando source legge ed esegue lo script, mentre getwd permette di controllare il riferimento corrente.''',richiamo='La procedura deve poter essere eseguita senza ricostruire manualmente lo stato della console.',origine='M02:1–15')
c=estratto('M02','percorso',"getwd()\nf <- file.path('dati','campioni_modulo1.csv')\nstopifnot(file.exists(f))\nd <- read.csv(f,stringsAsFactors=FALSE)\nstopifnot(nrow(d)==24L)\nstr(d)")
m.pagina('Il percorso viene verificato prima dell’importazione',
'''Quando un file risulta assente, il controllo deve riguardare la cartella corrente, il nome, l’estensione e la struttura del progetto. Modificare ripetutamente il percorso senza esaminarne la risoluzione può produrre una dipendenza dal computer utilizzato. Il codice costruisce il riferimento al CSV dalla radice del progetto, verifica che il file esista e controlla la numerosità dopo la lettura. L’ispezione dei tipi completa il controllo dell’ingresso prima delle trasformazioni.''',codice=c,richiamo='Un errore di percorso riguarda l’accesso al file; un errore di contenuto richiede controlli successivi.',origine='M02:7–13')
di=scrivi('M02','D01',n(3.7,.3,'Radice del progetto')+rect(.3,1.2,3.1,2.5)+n(1.7,1.85,'dati/',w=2.4)+rect(4.2,1.2,7,2.5,'Quantum')+n(5.6,1.85,'R/',w=2.4)+a(1.7,2.7,2.9,3.5)+a(5.6,2.7,4.4,3.5,'Quantum')+rect(2.2,3.5,5.2,4.8)+n(3.7,4.15,'risultati/',w=2.7)+n(3.7,5.7,'I percorsi sono relativi alla stessa radice.',w=6.7,size=11))
m.pagina('Le cartelle documentano le dipendenze',
'''Il diagramma distingue gli input acquisiti, il codice che li elabora e gli output rigenerabili. Questa organizzazione consente di individuare quali elementi debbano essere trasferiti affinché un’analisi possa essere ripetuta. Il contenuto della cartella dei risultati può essere ricostruito quando i sorgenti, gli input e l’ambiente necessario sono disponibili; il dato acquisito conserva invece il proprio ruolo di riferimento per la provenienza e per l’eventuale revisione delle decisioni.''',tikz=di,didascalia='Organizzazione del progetto distribuito. I nomi delle cartelle fanno parte dei percorsi utilizzati dagli script.',richiamo='La struttura del progetto deve essere coerente con i percorsi dichiarati nel codice.',origine='M02:8–9,14–15')
m.pagina('Ispezionare una funzione e i suoi errori',
'''Una funzione riceve argomenti, applica una procedura e restituisce un oggetto il cui significato dipende dalla documentazione. Quando l’esecuzione si interrompe, tipo del messaggio e posizione dell’errore aiutano a ricostruire quale condizione sia stata violata. La verifica deve partire dall’ingresso effettivo della funzione: una colonna numerica attesa può contenere testo, oppure un nome può riferirsi a un oggetto creato in precedenza. Un esempio ridotto rende più semplice isolare la causa.''',
'''Consultare la guida di read.csv e verificare gli argomenti relativi a separatori, decimali e mancanti. Riprodurre poi un errore usando un nome di file inesistente e un secondo errore usando una colonna assente. Distinguere il controllo necessario nei due casi prima di correggere lo script.''',richiamo='La documentazione collega gli argomenti della funzione al comportamento atteso.',origine='M02:10–12')

m.sezione_nuova('Vettori, tipi e selezioni')
m.pagina('Un vettore conserva tipo e posizione',
'''Un vettore atomico di R contiene elementi di un tipo comune, ordinati secondo le loro posizioni. Se un numero viene memorizzato come testo, il suo aspetto può restare invariato mentre cambiano le operazioni ammissibili. L’indicizzazione seleziona posizioni, nomi o condizioni logiche; per una tabella, la selezione delle righe deve essere applicata a tutte le colonne, affinché le misure dello stesso provino rimangano associate. Gli identificativi consentono di verificare questa corrispondenza anche dopo un ordinamento.''',
'''Il vettore c("5.4", "6.1", "ND") è testuale. La conversione richiede di riconoscere il codice di indisponibilità e di dichiarare come rappresentarlo. Una conversione che produca NA deve distinguere i mancanti previsti dai valori che non rispettano il formato atteso.''',richiamo='La conversione del tipo deve conservare il significato delle registrazioni originali.',origine='M02:16–20,24–25')
c=estratto('M02','selezione',"d <- read.csv('dati/campioni_modulo1.csv')\nsel <- d$affioramento=='A' & d$volume_cm3>=40\ns <- d[sel,c('id','massa_g','volume_cm3')]\ns <- s[order(s$volume_cm3),]\nstopifnot(all(s$id %in% d$id))\ns$densita <- s$massa_g / s$volume_cm3")
m.pagina('Una condizione logica definisce un sottoinsieme',
'''La selezione combina appartenenza all’affioramento e volume minimo, rendendo esplicite le condizioni che determinano l’inclusione. L’ordinamento successivo riguarda tutte le colonne della tabella selezionata. La densità viene quindi calcolata su misure che conservano la medesima corrispondenza fra righe. Poiché il filtro modifica l’insieme descritto, la sintesi dei valori selezionati dovrà indicare anche il criterio di inclusione, oltre alla provenienza dei dati.''',codice=c,formula=r'\mathcal S=\{i:A_i=A,\ V_i\ge40\}',richiamo='La condizione usata nel filtro appartiene alla definizione del risultato.',origine='M02:19–20,37–40')
m.pagina('Il riciclo richiede lunghezze compatibili',
'''Le operazioni vettoriali combinano elementi secondo le regole del linguaggio. Quando le lunghezze differiscono, R può ripetere il vettore più corto, producendo un risultato che non coincide con l’intenzione scientifica dell’operazione. Anche quando la lunghezza maggiore è un multiplo di quella minore e manca un avvertimento, la corrispondenza deve essere giustificata. Per il rapporto massa–volume, ogni misura deve avere un denominatore riferito allo stesso provino, salvo che un denominatore comune sia esplicitamente previsto.''',formula=r'\rho_i=m_i/V_i,\qquad i=1,\ldots,n',destra='Una funzione dedicata può richiedere lunghezze uguali e interrompersi quando il vincolo viene violato. La possibilità tecnica di riciclare un vettore non costituisce una giustificazione del significato della trasformazione.',richiamo='Le regole di riciclo devono essere controllate quando una posizione corrisponde a un’unità osservativa.',origine='M02:21')
di=scrivi('M02','D02',n(3.7,.3,'Selezione delle righe')+n(1.1,1.3,'ID')+n(3.5,1.3,'Massa')+n(6,1.3,'Volume')+linea(.3,1.8,7.1,1.8)+n(1.1,2.4,'C01')+n(3.5,2.4,'107,2')+n(6,2.4,'40')+rect(.3,3,7.1,4.1,'Quantum',8)+n(1.1,3.55,'C02')+n(3.5,3.55,'121,95')+n(6,3.55,'45')+n(1.1,4.9,'C03')+n(3.5,4.9,'132,5')+n(6,4.9,'50')+n(3.7,6,'La riga selezionata conserva tutte le corrispondenze.',w=7,size=10.6))
m.pagina('Categorie e date hanno regole proprie',
'''I fattori conservano livelli categoriali che possono essere ordinati soltanto quando la scala di misura lo consente. Le date richiedono invece una convenzione esplicita per giorno, mese e anno, così che ordinamento e differenze temporali possano essere interpretati. Il diagramma ricorda che anche queste informazioni appartengono alle righe della tabella: separare l’ordinamento della data da quello delle misure altererebbe la successione del fenomeno, pur lasciando intatti i valori nelle singole colonne.''',tikz=di,didascalia='Le unità delle misure sono grammi e centimetri cubi. L’evidenziazione riguarda un’intera osservazione.',richiamo='Ordinamenti e filtri devono conservare la relazione fra identificativi, categorie, date e misure.',origine='M02:22–23,39')

m.sezione_nuova('Importazione e conversioni')
m.pagina('Il formato del file richiede convenzioni',
'''L’estensione CSV identifica una famiglia di file testuali, ma non stabilisce in modo univoco separatore di campo, simbolo decimale e codici dei mancanti. Un’importazione corretta deve dichiarare tali convenzioni e confrontare la struttura ottenuta con quella attesa. Nel file dei fossili da controllare, il separatore è il punto e virgola e alcune misure usano la virgola decimale. Leggere inizialmente le colonne come testo permette di conservare le registrazioni prima della conversione.''',
'''Un foglio elettronico richiede inoltre la scelta di foglio, intervallo e riga delle intestazioni. Celle formattate, formule e note possono appartenere a livelli diversi dal dato tabellare. Il rapporto di importazione deve indicare quali elementi siano stati letti e come siano stati riconosciuti i tipi delle colonne.''',richiamo='Le convenzioni di importazione fanno parte della procedura scientifica.',origine='M02:26–33')
c=estratto('M02','importa',"raw <- read.csv(\n 'dati/fossili_da_controllare.csv',\n sep=';',colClasses='character',\n na.strings=character())\nraw$riga_origine <- seq_len(nrow(raw))\nstopifnot(nrow(raw)==25L)\nhead(raw)")
m.pagina('La prima lettura conserva il testo',
'''L’importazione conservativa evita che un codice speciale venga trasformato prima che ne sia stato verificato il significato. La colonna aggiunta con il numero della riga di origine permette di rintracciare una registrazione anche quando gli identificativi contengono duplicati. Il controllo della numerosità conferma la forma iniziale del file, mentre la lettura delle prime righe consente di esaminare separatori e convenzioni. La conversione viene eseguita in una tabella derivata, mantenendo accessibile questa rappresentazione iniziale.''',codice=c,richiamo='Il testo originale permette di distinguere un dato mancante da una conversione fallita.',origine='M02:27–34,98')
m.pagina('Quantificare le segnalazioni dell’audit',
'''Il riepilogo mostra quante righe presentino alcune condizioni da esaminare: identificativi ripetuti, misura esterna assente, valore non positivo o diametro interno maggiore di quello esterno. Le categorie descrivono controlli distinti e possono sovrapporsi nella stessa riga; la loro somma non rappresenta quindi automaticamente il numero di osservazioni da escludere. La decisione analitica viene formulata soltanto dopo avere ricostruito quali condizioni siano presenti e quale evidenza permetta di correggerle.''',figura='M02/F01',didascalia='Segnalazioni nel file didattico di 25 righe. I conteggi si riferiscono a controlli potenzialmente sovrapposti.',richiamo='Il numero delle segnalazioni e il numero delle righe coinvolte sono quantità differenti.',origine='M02:29–33,63,73')
di=scrivi('M02','D03',rect(.3,.7,3,2)+n(1.65,1.35,'Testo originale',w=2.4)+a(3.2,1.35,4,1.35)+rect(4.2,.7,7,2,'Quantum')+n(5.6,1.35,'Conversione',w=2.4)+a(5.6,2.2,5.6,3)+n(5.6,3.6,'Numero valido',w=2.8)+a(4.3,2.2,2.1,3,'Quantum')+n(1.9,3.6,'Codice mancante o errore di formato',w=3.5,size=11)+n(3.7,5.5,'Il registro conserva l’esito per ogni valore.',w=6.7,size=11))
m.pagina('Una conversione deve avere un esito',
'''La conversione distingue almeno tre situazioni: un numero riconosciuto, un codice di indisponibilità previsto e una stringa che non rispetta il formato atteso. Sebbene le ultime due possano essere rappresentate numericamente da NA, la loro provenienza deve rimanere distinguibile nel registro. Un valore con simbolo di censura richiede un trattamento specifico, poiché contiene un limite quantitativo. Il diagramma esplicita perché la sola presenza di NA nella colonna finale sia insufficiente a ricostruire la conversione.''',tikz=di,didascalia='La classificazione degli esiti accompagna la colonna numerica derivata.',richiamo='Ogni conversione fallita deve essere rintracciabile nel testo da cui proviene.',origine='M02:30,33–35,98')

m.sezione_nuova('Trasformazioni e aggregazioni')
m.pagina('La sintesi cambia il livello della tabella',
'''Il raggruppamento riunisce osservazioni che condividono una chiave e applica una sintesi alle loro misure. Una tabella con una riga per provino può così diventare una tabella con una riga per stazione. La trasformazione modifica il significato della riga e richiede nuove definizioni per numerosità, media e disponibilità. Il numero dei valori effettivamente utilizzati deve essere riportato insieme alla sintesi, poiché può differire fra variabili o gruppi.''',formula=r'\bar x_g=\frac1{n_g}\sum_{i\in g}x_i',destra='Se alcune misure sono assenti, il denominatore della media dei disponibili è il loro numero effettivo. La numerosità totale del gruppo rimane utile per documentare la copertura.',richiamo='Una riga aggregata rappresenta un gruppo, con proprietà e limiti diversi da quelli delle righe originarie.',origine='M02:36–43')
c=estratto('M02','aggrega',"d <- read.csv('dati/campioni_modulo1.csv')\nd$densita <- d$massa_g/d$volume_cm3\nsintesi <- function(x) c(\n n=length(x), disponibili=sum(!is.na(x)),\n media=mean(x,na.rm=TRUE), sd=sd(x,na.rm=TRUE))\naggregate(densita ~ stazione,d,sintesi,\n          na.action=na.pass)")
m.pagina('Associare la sintesi al suo denominatore',
'''La funzione restituisce il numero dei valori, quello delle osservazioni disponibili, la media e la deviazione standard. Applicandola per stazione, si ottengono sintesi la cui interpretazione rimane collegata alla quantità di dati utilizzata. In un caso con tutti i valori mancanti, media e dispersione richiederebbero una gestione esplicita; nel dataset dei provini questa condizione viene esclusa dai controlli di ingresso. L’esempio mostra come una funzione possa rendere uniforme la definizione della sintesi fra gruppi.''',codice=c,richiamo='L’esclusione dei mancanti dal calcolo deve essere accompagnata dal conteggio dei valori disponibili.',origine='M02:41–45,89')
m.pagina('Confrontare i conteggi con il disegno',
'''Le sei stazioni contengono ciascuna quattro provini, come previsto nel disegno del caso guida. La figura rende immediato il controllo dell’equilibrio della raccolta, mentre una tabella degli identificativi permette di verificare che i conteggi derivino da unità distinte. Se una stazione avesse meno osservazioni, occorrerebbe stabilire se la differenza dipenda dalla raccolta, dall’indisponibilità di misure o da un filtro applicato successivamente.''',figura='M02/F02',didascalia='Numero dei provini per stazione nel dataset sintetico. Il grafico descrive la raccolta e non la numerosità effettiva di un modello inferenziale.',richiamo='Le differenze di numerosità devono essere ricondotte al processo che le ha prodotte.',origine='M02:41–45')
di=scrivi('M02','D04',n(1.6,.4,'Provini')+n(5.8,.4,'Stazioni')+rect(.3,1,2.9,4.8)+rect(4.4,2,7.1,3.9,'Quantum')+n(1.6,1.7,'A1 · C01')+n(1.6,2.6,'A1 · C02')+n(1.6,3.5,'A1 · C03')+n(1.6,4.4,'A1 · C04')+a(3.1,2.9,4.2,2.9)+n(5.75,2.65,r'$\bar x_{A1}$')+n(5.75,3.35,r'$n_{A1}=4$')+n(3.7,5.6,'Una riga di sintesi conserva una chiave di gruppo.',w=6.7,size=11))
m.pagina('L’aggregazione deve conservare la chiave',
'''La media di stazione riassume quattro provini, ma deve rimanere associata al codice del sito affinché possa essere collegata a coordinate, quota e altre caratteristiche locali. Il diagramma rappresenta la riduzione delle righe, accompagnata dal cambiamento della loro unità. Se la chiave fosse eliminata, la posizione della sintesi nella tabella diventerebbe l’unico riferimento, esponendo i collegamenti successivi a errori di ordinamento.''',tikz=di,didascalia='Aggregazione dei quattro provini della stazione A1; il risultato conserva media, numerosità e identificativo del gruppo.',richiamo='La chiave del gruppo deve accompagnare ogni sintesi destinata a un collegamento successivo.',origine='M02:38,41,49')

m.sezione_nuova('Chiavi e relazioni fra tabelle')
m.pagina('Una chiave identifica l’unità dichiarata',
'''Una chiave deve essere univoca rispetto all’unità rappresentata dalla tabella. Il codice del provino può identificare una riga nella tabella dei campioni, mentre il codice della stazione si ripete quando più provini provengono dallo stesso sito. Prima di collegare tabelle occorre quindi stabilire quale relazione sia attesa: uno-a-uno, molti-a-uno oppure molti-a-molti. Il significato della chiave determina quali controlli di unicità siano appropriati su ciascun lato.''',formula=r'k:\mathcal U\to\mathcal K,\qquad k(u)=k(v)\Rightarrow u=v',destra='La proprietà di iniettività riguarda la chiave dell’unità della tabella. Una chiave esterna, come la stazione nella tabella dei provini, può ripetersi perché esprime l’appartenenza a un gruppo.',richiamo='L’unicità deve essere valutata al livello dell’unità rappresentata dalla tabella.',origine='M02:46–51,53')
c=estratto('M02','join',"campioni <- data.frame(id=c('p1','p2','p3'),\n sito=c('A','A','B'))\nsiti <- data.frame(sito=c('A','B'),quota=c(10,20))\nstopifnot(!anyDuplicated(siti$sito))\nj <- merge(campioni,siti,by='sito',all.x=TRUE)\nstopifnot(nrow(j)==nrow(campioni))\nstopifnot(!anyNA(j$quota))")
m.pagina('Controllare un collegamento molti-a-uno',
'''La tabella delle stazioni contiene una sola quota per sito, mentre quella dei campioni può contenere più provini dello stesso sito. Il collegamento trasferisce la quota a ogni provino corrispondente, conservando tutte le righe della tabella dei campioni. Il controllo di unicità sul lato delle stazioni previene la moltiplicazione delle righe; il controllo dei valori mancanti dopo l’unione segnala invece eventuali chiavi prive di corrispondenza.''',codice=c,richiamo='La cardinalità attesa del collegamento deve essere dichiarata prima di eseguire l’unione.',origine='M02:49–55')
m.pagina('Le molteplicità determinano il numero di righe',
'''Se una chiave compare due volte in ciascuna delle tabelle, il collegamento produce quattro combinazioni per quella chiave. In generale, il numero delle righe di un inner join è la somma dei prodotti delle molteplicità sui due lati. La figura mostra un esempio nel quale tre provini e tre registrazioni di sito producono cinque righe. Il risultato può essere formalmente corretto rispetto all’operazione, pur violando la relazione scientifica attesa fra provino e stazione.''',formula=r'n_{\mathrm{join}}=\sum_k n_L(k)n_R(k)',figura='M02/F04',didascalia='La chiave A compare due volte su entrambi i lati; B compare una volta. Il join contiene 2×2 + 1×1 = 5 righe.',richiamo='Un aumento delle righe può rivelare una molteplicità della chiave incompatibile con il collegamento previsto.',origine='M02:49–55')
di=scrivi('M02','D05',n(1.4,.5,'Provini')+n(6,.5,'Siti')+n(1.4,2,'p1 · A')+n(1.4,4.1,'p2 · A')+n(6,2,'A · 10 m')+n(6,4.1,'A · 12 m')+a(2.5,2,4.8,2)+a(2.5,2.2,4.8,3.9,'Quantum')+a(2.5,3.9,4.8,2.2,'Quantum')+a(2.5,4.1,4.8,4.1)+n(3.7,5.65,'Due provini × due registrazioni = quattro righe',w=6.9,size=11))
m.pagina('Duplicati e misure ripetute vanno distinti',
'''Due registrazioni dello stesso sito possono rappresentare un duplicato accidentale oppure misure eseguite in tempi o condizioni differenti. Nel secondo caso, la chiave deve includere le informazioni che distinguono le osservazioni, come data e protocollo. Il diagramma mostra perché eliminare o conservare tutte le righe senza esaminarne il significato possa alterare il collegamento. La struttura lunga della tabella rende esplicite le ripetizioni quando a ogni riga vengono associate unità, occasione e misura.''',tikz=di,didascalia='Combinazioni prodotte dalla chiave A ripetuta su entrambi i lati. Le quote sono illustrative.',richiamo='La scelta della chiave deve distinguere le ripetizioni reali dai duplicati del processo di registrazione.',origine='M02:48,51–55')

m.sezione_nuova('Mancanti e censura')
m.pagina('La disponibilità va definita per ogni analisi',
'''Un valore NA rappresenta l’indisponibilità della misura, mentre una data assente da una serie può costituire un mancante implicito che emerge soltanto ricostruendo la griglia temporale attesa. Se un modello utilizza più variabili, il sottoinsieme delle righe complete dipende da tutte le colonne richieste. La popolazione descritta dopo questa selezione può differire da quella iniziale, soprattutto quando la disponibilità è associata al fenomeno osservato. Il numero delle esclusioni deve quindi essere accompagnato da una descrizione dei loro motivi.''',
'''Una registrazione inferiore al limite di rilevabilità mantiene invece un vincolo quantitativo. Nel file di esempio, valore osservato, limite e stato sono conservati in colonne distinte, così che la successiva analisi possa utilizzare l’informazione disponibile senza attribuire un valore puntuale arbitrario.''',richiamo='Disponibilità e censura richiedono rappresentazioni capaci di conservarne il significato.',origine='M02:56–65')
m.pagina('L’imputazione media modifica la dispersione',
'''Se i valori mancanti vengono sostituiti con la media dei disponibili, la media finale rimane invariata, mentre i nuovi scarti dalla media sono tutti nulli. La somma dei quadrati degli scarti conserva quindi il valore precedente, ma viene divisa per un denominatore maggiore nel calcolo della varianza campionaria. La riduzione della dispersione deriva dall’operazione stessa. Per valutare l’incertezza dopo un’imputazione occorre considerare anche l’informazione assente e le ipotesi utilizzate per ricostruirla.''',formula=r's_{\mathrm{imp}}^2=\frac{n_o-1}{n-1}s_o^2,\qquad n\ge n_o>1',destra='Qui n indica il numero totale delle righe e n_o quello dei valori osservati. L’identità vale quando ogni valore aggiunto coincide con la media dei disponibili e si usa il denominatore campionario n−1.',richiamo='La dispersione introdotta dall’imputazione non rappresenta nuove misure.',origine='M02:61–62')
m.pagina('La distribuzione conserva il segno dell’intervento',
'''Nel confronto grafico, sei diametri sono resi indisponibili e successivamente sostituiti con la media dei restanti. La concentrazione di valori identici può modificare la forma della distribuzione, anche quando la media resta quella dei disponibili. La stima di densità rende visibile l’effetto, ma dipende dalla propria regola di lisciamento; l’identità sulla varianza fornisce il controllo algebrico indipendente. L’esempio serve a esaminare una trasformazione, senza proporla come trattamento generale dei mancanti.''',figura='M02/F03',didascalia='Esempio sui fossili sintetici: 154 valori disponibili e sei imputazioni con la loro media.',richiamo='Una trasformazione deve essere valutata attraverso proprietà numeriche e conseguenze interpretative.',origine='M02:62–63')
di=scrivi('M02','D06',n(3.7,.35,'Registrazione della concentrazione')+rect(.3,1.1,2.35,4.7)+rect(2.65,1.1,4.7,4.7,'Quantum')+rect(5,1.1,7.1,4.7,'Measure')+n(1.32,1.7,'Valore',w=1.8)+n(3.67,1.7,'Limite',w=1.8)+n(6.05,1.7,'Stato',w=1.8)+n(1.32,2.8,'0,12')+n(3.67,2.8,'NA')+n(6.05,2.8,'misurato',w=1.8,size=10.6)+n(1.32,3.9,'NA')+n(3.67,3.9,'0,05')+n(6.05,3.9,'censurato',w=1.8,size=10.6)+n(3.7,5.7,'Il simbolo < viene conservato nello stato.',w=6.8,size=11))
m.pagina('Conservare limite e stato della registrazione',
'''Il dato censurato viene rappresentato senza attribuirgli una misura esatta. La colonna del valore rimane indisponibile, il limite registra la soglia applicabile e lo stato identifica la natura dell’informazione. In questo modo, una procedura successiva può distinguere la censura dalla semplice assenza di dati. Se i limiti cambiano fra strumenti o campioni, il valore specifico deve essere conservato per ogni osservazione, affinché il modello possa utilizzarlo correttamente.''',tikz=di,didascalia='Struttura del file censura_esempio.csv; le due righe rappresentano una misura e una registrazione inferiore al limite.',richiamo='Il limite è una proprietà dell’osservazione e del metodo con cui è stata ottenuta.',origine='M02:60,64–65')

m.sezione_nuova('Coerenza fisica e registro delle decisioni')
m.pagina('I vincoli possono coinvolgere più colonne',
'''Un valore può essere plausibile isolatamente e incompatibile con un’altra misura dello stesso oggetto. Per un fossile, un diametro interno maggiore di quello esterno viola la geometria adottata, anche quando entrambi i numeri rientrano in un intervallo ordinario. Il controllo congiunto deve quindi precedere il calcolo dello spessore. Altri criteri, come una fascia attorno al totale degli ossidi, hanno invece un carattere diagnostico che richiede informazioni sul materiale e sul metodo analitico.''',formula=r'0\le D_{\mathrm{int}}\le D_{\mathrm{est}},\qquad D_{\mathrm{est}}>0',destra='Il controllo segnala le righe incompatibili con il modello geometrico. La correzione di una misura richiede il confronto con il dato originale; una soglia statistica non identifica da sola la causa di un’anomalia.',richiamo='Vincoli definitori e criteri empirici devono essere documentati separatamente.',origine='M02:66–74')
m.pagina('La bisettrice rappresenta un limite geometrico',
'''Nel piano dei due diametri, la bisettrice corrisponde all’uguaglianza fra misura interna ed esterna. I punti al di sopra sono incompatibili con la definizione geometrica utilizzata, mentre valori esterni non positivi impediscono di interpretare il rapporto fra diametri. La figura permette di identificare queste condizioni e di collegarle alle righe del registro. I punti lontani dal gruppo principale ma compatibili con i vincoli richiedono invece una valutazione della loro origine.''',figura='M02/F05',didascalia='Fossili del file da controllare. Il tratteggio indica D interno = D esterno; le misure assenti non vengono rappresentate.',richiamo='Un grafico di controllo deve rendere riconoscibile la condizione che viene verificata.',origine='M02:68–70,74–75')
c=estratto('M02','geometria',"esterno <- c(8,5,NA,7)\ninterno <- c(6,6,4,5)\ndisponibile <- is.finite(esterno) & is.finite(interno)\nvalido <- disponibile & esterno>0 &\n          interno>=0 & interno<=esterno\nvalido[is.na(valido)] <- FALSE\ndata.frame(esterno,interno,disponibile,valido)")
m.pagina('Le condizioni devono avere un esito definito',
'''Un confronto che coinvolge un valore mancante può produrre NA, anziché TRUE o FALSE. Prima di usare una condizione per filtrare la tabella, occorre quindi definirne il comportamento sui valori indisponibili. Il codice distingue la disponibilità dalla compatibilità geometrica e assegna un esito esplicito alla selezione. La distinzione rimane utile nel registro, perché una misura assente e una misura incompatibile richiedono verifiche differenti sulla fonte.''',codice=c,richiamo='Una condizione di inclusione deve essere interpretabile anche quando alcuni ingressi sono mancanti.',origine='M02:67–69,74–75')
di=scrivi('M02','D07',n(3.7,.3,'Esame della registrazione')+n(1.8,1.6,'Disponibile?',w=3,color='Classical')+a(3.4,1.6,4.1,1.6)+n(5.7,1.6,'Compatibile?',w=3,color='Quantum')+a(1.8,2.2,1.8,3.6)+a(5.7,2.2,5.7,3.6,'Quantum')+n(1.8,4.2,'Motivo dell’assenza',w=3)+n(5.7,4.2,'Evidenza sull’anomalia',w=3)+n(3.7,5.65,'Il registro documenta motivo, evidenza e decisione.',w=6.9,size=11))
m.pagina('Il registro consente di rivedere una scelta',
'''Ogni intervento viene associato alla riga di origine, al controllo che l’ha segnalata, all’evidenza utilizzata e alla decisione finale. Se nuove informazioni chiariscono che un valore insolito è valido, la procedura può essere rieseguita modificando la regola pertinente. Questa tracciabilità è particolarmente utile quando un filtro influenza numerose analisi successive. Il diagramma distingue l’esame della disponibilità da quello della compatibilità, così che le ragioni dell’intervento restino identificabili.''',tikz=di,didascalia='Schema di organizzazione del registro; gli esiti del controllo non implicano una correzione automatica.',richiamo='Una decisione riproducibile deve poter essere ricondotta all’evidenza che la sostiene.',origine='M02:72–75,103–105')

m.sezione_nuova('Variabili derivate e composizione chimica')
m.pagina('La formula introduce relazioni fra colonne',
'''Lo spessore radiale del modello adottato è metà della differenza fra diametro esterno e interno. Una volta aggiunto alla tabella, esso conserva una relazione algebrica esatta con le due misure originarie. Usare tutte e tre le colonne come informazioni indipendenti introdurrebbe una ridondanza che può alterare l’interpretazione di correlazioni, distanze e modelli. La formula deve quindi essere riportata nel dizionario insieme alle condizioni geometriche che ne permettono l’uso.''',formula=r's=\frac{D_{\mathrm{est}}-D_{\mathrm{int}}}{2},\qquad D_{\mathrm{est}}-D_{\mathrm{int}}-2s=0',figura='M02/F06',didascalia='Diametro esterno e spessore radiale nei fossili sintetici; lo spessore è una grandezza derivata.',richiamo='Le variabili derivate conservano le dipendenze determinate dalle loro definizioni.',origine='M02:76–80,84–85')
di=scrivi('M02','D08',r'\draw[Classical,fill=Classical!10,line width=1pt] (3.7,2.9) ellipse (2 and 2.29885);\draw[Quantum,fill=Paper,line width=1pt] (3.7,2.9) ellipse (1.35 and 1.55172);'+r'\draw[<->,Classical,line width=.8pt] (1.7,2.9)--(5.7,2.9);\draw[<->,Quantum,line width=.8pt] (3.7,1.34828)--(3.7,4.45172);'+n(3.7,.1,'Sezione ideale della parete')+n(2.65,2.25,r'$D_{\rm est}$',size=11)+n(4.5,4.15,r'$D_{\rm int}$',size=11)+n(3.7,5.7,r'$s=(D_{\rm est}-D_{\rm int})/2$'))
m.pagina('Lo spessore richiede un modello geometrico',
'''Il diagramma rappresenta una sezione circolare ideale nella quale la differenza fra i diametri comprende due tratti di parete. La divisione per due deriva da questa simmetria. Per un oggetto irregolare, la medesima formula può definire un indicatore convenzionale, ma il rapporto con lo spessore locale deve essere motivato dal protocollo. L’esplicitazione del modello geometrico permette di distinguere il calcolo corretto dell’indicatore dalla sua interpretazione morfologica.''',tikz=di,didascalia='Sezione ideale concentrica. Le frecce indicano i diametri utilizzati nella formula.',richiamo='Una definizione geometrica deve essere coerente con il protocollo di misura.',origine='M02:78–80,84–85')
m.pagina('Le masse degli ossidi vanno convertite in moli',
'''Il rapporto molare fra magnesio e ferro richiede di convertire le percentuali in massa degli ossidi usando le rispettive masse molari e la stechiometria. Assumendo una base di cento grammi e trattando il ferro riportato come FeO, ogni mole di MgO e FeO contribuisce con una mole del rispettivo catione. Il rapporto ottenuto differisce da quello calcolato direttamente sulle masse. La convenzione sullo stato del ferro e sulla forma del rapporto deve essere dichiarata.''',formula=r'n_{\rm Mg}=\frac{w_{\rm MgO}}{40{,}304},\quad n_{\rm Fe}=\frac{w_{\rm FeO}}{71{,}844},\\X_{\rm Mg}=\frac{n_{\rm Mg}}{n_{\rm Mg}+n_{\rm Fe}}',destra='Le masse molari sono espresse in g/mol. Qui X_Mg è una frazione fra zero e uno; la convenzione che esprime Mg# fra zero e cento usa 100 X_Mg. La presenza di ferro ferrico richiederebbe un trattamento coerente con l’obiettivo mineralogico.',richiamo='Una convenzione chimica deve essere definita prima dell’interpretazione del rapporto.',origine='M02:81–85')
m.pagina('Rapporto in massa e rapporto molare',
'''La figura confronta i due rapporti per le analisi sintetiche di microsonda. Lo scostamento dalla bisettrice deriva dalle differenti masse molari degli ossidi, che modificano i pesi dei cationi nel denominatore. L’associazione fra i due indici non li rende intercambiabili: una soglia mineralogica definita per il rapporto molare deve essere applicata alla quantità corrispondente. Le fasi del dataset identificano la costruzione didattica e non costituiscono classificazioni validate su campioni reali.''',figura='M02/F07',didascalia='Analisi sintetiche. Il rapporto sull’asse orizzontale usa le masse degli ossidi; quello verticale usa le moli dei cationi.',richiamo='La definizione del rapporto determina quali confronti mineralogici siano ammissibili.',origine='M02:81–83')

m.sezione_nuova('Funzioni, parametri e controlli')
m.pagina('Una funzione delimita ingressi e risultati',
'''Una funzione riunisce una trasformazione definita, rendendo espliciti gli argomenti necessari e la struttura del risultato. I controlli iniziali verificano le condizioni nelle quali la formula ha significato; i parametri permettono di modificare una scelta senza cercarla in più punti dello script. Questa organizzazione facilita il confronto fra gruppi e l’esecuzione ripetuta, purché la funzione conservi un compito circoscritto e il chiamante possa riconoscere eventuali modifiche agli oggetti o ai file.''',
'''Nel laboratorio, una funzione di sintesi riceve un vettore e restituisce numerosità, media e dispersione. Una funzione per la densità richiede invece masse e volumi coerenti. Le due procedure possono essere composte nello script, mantenendo visibili i controlli di ingresso e il significato delle quantità restituite.''',richiamo='Le condizioni di applicabilità appartengono alla definizione della funzione.',origine='M02:86–95')
c=estratto('M02','molare',"frazione_Mg <- function(MgO,FeO) {\n stopifnot(length(MgO)==length(FeO))\n stopifnot(all(is.finite(MgO)),all(is.finite(FeO)))\n stopifnot(all(MgO>=0),all(FeO>=0))\n a <- MgO/40.304; b <- FeO/71.844\n stopifnot(all(a+b>0))\n a/(a+b)\n}\nstopifnot(frazione_Mg(40.304,71.844)==0.5)")
m.pagina('Un caso stechiometrico verifica la funzione',
'''Quando le masse dei due ossidi corrispondono a una mole ciascuna, il rapporto dei cationi deve essere un mezzo. Questo caso fornisce una risposta nota indipendente dal dataset di microsonda e permette di verificare che la funzione utilizzi la conversione molare. I controlli escludono lunghezze incompatibili, valori non finiti, masse negative e denominatori nulli. Il risultato rimane una quantità convenzionale, la cui interpretazione mineralogica richiede le ipotesi sul ferro già dichiarate.''',codice=c,richiamo='Il controllo su un caso noto verifica la definizione implementata, oltre alla sola esecuzione del codice.',origine='M02:81–83,87–90')
di=scrivi('M02','D09',rect(.3,.7,3.05,2)+n(1.67,1.35,'Ingressi e unità',w=2.5)+rect(4.1,.7,7.1,2,'Quantum')+n(5.6,1.35,'Parametri dichiarati',w=2.6)+a(1.7,2.2,2.9,3)+a(5.6,2.2,4.4,3,'Quantum')+rect(2.2,3,5.2,4.3)+n(3.7,3.65,'Funzione verificata',w=2.6)+a(3.7,4.5,3.7,5)+n(3.7,5.55,'Risultato con significato definito',w=6.5,size=11))
m.pagina('Parametri e stato casuale sono dipendenze',
'''Soglie, convenzioni e semi casuali determinano il risultato insieme ai dati e al codice. Riunirli in una sezione identificabile facilita la ricostruzione di un’esecuzione e il confronto fra scenari. Il seme inizializza un generatore specifico; versioni e algoritmi devono essere registrati quando si richiede una riproduzione numerica. I commenti spiegano il motivo delle scelte meno evidenti, mentre le istruzioni esprimono le operazioni necessarie a realizzarle.''',tikz=di,didascalia='Dipendenze della procedura. Per le simulazioni, il registro comprende generatore, seme e ambiente.',richiamo='La riproducibilità richiede di conservare le scelte che influenzano l’esecuzione.',origine='M02:87–95')
m.pagina('Una soglia analitica richiede una motivazione',
'''Il totale degli ossidi può segnalare un problema di analisi, una componente non misurata o una caratteristica del materiale. Una fascia attorno al cento per cento può essere utile come controllo preliminare, purché sia coerente con il metodo e con la composizione attesa. La figura descrive i totali delle analisi sintetiche prima dell’applicazione di un filtro. Il loro confronto deve considerare la natura delle fasi e le convenzioni con cui sono stati ottenuti i valori.''',figura='M02/F08',didascalia='Totali in percentuale di massa nelle analisi sintetiche. Le classi dell’istogramma hanno ampiezza 0,5 punti percentuali.',richiamo='Il totale degli ossidi è un indicatore da interpretare rispetto al protocollo analitico.',origine='M02:71,91')

m.sezione_nuova('Tabella analitica e consegna')
m.pagina('La soglia determina la copertura finale',
'''Allargando la tolleranza attorno al cento per cento aumenta il numero delle analisi mantenute. Il grafico descrive questa relazione operativa, senza identificare una soglia ottimale. La scelta deve essere motivata da caratteristiche del metodo e dell’applicazione, mentre l’analisi di sensibilità permette di documentarne le conseguenze. Se un risultato scientifico dipende fortemente da una fascia ristretta di soglie, tale dipendenza deve essere riportata insieme alla conclusione.''',figura='M02/F09',didascalia='Numero delle analisi sintetiche con totale degli ossidi compreso entro la tolleranza indicata rispetto a 100.',richiamo='La sensibilità documenta l’effetto di una scelta; la sua giustificazione richiede informazioni sul metodo.',origine='M02:91,99–103')
m.pagina('Confrontare le distribuzioni prima e dopo i controlli',
'''La distribuzione empirica dei diametri viene confrontata prima e dopo alcuni controlli dichiarati su identificativi e geometria. Lo scarto fra le curve rende visibile come il sottoinsieme analitico differisca dalle registrazioni importate. Le curve utilizzano ciascuna il proprio denominatore di valori disponibili; il confronto deve essere accompagnato dai relativi conteggi. Questa rappresentazione consente di esaminare l’effetto delle decisioni senza nascondere i valori esclusi dalla procedura.''',figura='M02/F10',didascalia='Controlli illustrati: ID duplicato, indisponibilità e compatibilità dei due diametri. Il registro completo dei laboratori include ulteriori condizioni dichiarate.',richiamo='Il confronto fra input e tabella analitica rende valutabili le conseguenze dei filtri.',origine='M02:97–105')
c=estratto('M02','roundtrip',"d <- read.csv('dati/campioni_modulo1.csv')\ndir.create('risultati',showWarnings=FALSE)\nf <- 'risultati/controllo_esportazione.csv'\nwrite.csv(d,f,row.names=FALSE,na='')\nr <- read.csv(f,stringsAsFactors=FALSE)\nstopifnot(identical(d$id,r$id))\nstopifnot(isTRUE(all.equal(d$massa_g,r$massa_g)))")
m.pagina('La consegna viene riletta e rieseguita',
'''La rilettura verifica che il file esportato conservi identificativi e misure entro la precisione prevista. La riesecuzione da una sessione pulita verifica invece che il progetto contenga tutti gli input e che lo script ricostruisca le trasformazioni. I due controlli riguardano aspetti diversi della consegna e devono essere interpretati insieme. Il rapporto finale descrive inoltre quali valori rimangano incerti o incompatibili, così che la tabella derivata possa essere utilizzata conoscendone i limiti.''',codice=c,richiamo='Un file leggibile e una procedura ricostruibile sono entrambe condizioni della consegna.',origine='M02:43,100–107')
di=scrivi('M02','D10',n(3.7,.4,'Controllo della consegna')+rect(.3,1.2,3.1,2.7)+n(1.7,1.95,'File esportato',w=2.5)+rect(4.2,1.2,7,2.7,'Quantum')+n(5.6,1.95,'File riletto',w=2.5)+a(3.25,1.95,4,1.95)+n(1.7,4,'Chiavi originali',w=2.7)+n(5.6,4,'Chiavi ricostruite',w=2.7)+linea(1.7,2.9,1.7,3.5)+linea(5.6,2.9,5.6,3.5,'Quantum')+n(3.7,5.55,'Confrontare identità, tipi e valori.',w=6.5))
m.pagina('Valutare il risultato della preparazione',
'''La tabella analitica viene consegnata insieme al dizionario aggiornato, al registro degli interventi e al codice che la produce. Per valutarla, un lettore deve poter ricostruire quali unità siano presenti, quali misure siano disponibili e come siano state definite le variabili derivate. La verifica finale consiste nel descrivere queste proprietà e nel riconoscere quali decisioni possano influenzare le analisi successive. La pulizia del dato rimane quindi parte dell’argomentazione scientifica.''',tikz=di,didascalia='Il confronto fra file esportato e riletto viene applicato alle chiavi e alle colonne rilevanti.',richiamo='La preparazione dei dati produce un insieme documentato di osservazioni e trasformazioni.',origine='M02:102–110')
m.sezione_nuova('Fonti e laboratori')
m.pagina('Documentazione delle operazioni utilizzate',
'''I venti laboratori del modulo sviluppano importazione, conversione, indicizzazione, raggruppamento, collegamento, censura e variabili chimiche derivate. Gli script sono eseguibili dalla radice del progetto e conservano nei risultati le verifiche pertinenti. Le figure delle slide vengono prodotte da un sorgente R separato, che usa la medesima palette e registra i controlli numerici degli esempi. Le funzioni standard possono essere approfondite attraverso la documentazione distribuita con R.''',
r'''R Core Team, An Introduction to R: vettori, fattori, liste e data frame.\par\medskip Manuale R Data Import/Export: convenzioni dei file e importazione.\par\medskip Documentazione di read.csv, merge, aggregate, complete.cases e write.csv.\par\medskip Wickham, Çetinkaya-Rundel e Grolemund, R for Data Science, seconda edizione: importazione, trasformazioni e relazioni.''',richiamo='La versione dell’ambiente effettivamente collaudato è riportata nei registri del progetto.',fonti='R; R4DS; CORSO',origine='M02:108–109')
m.salva()
